from fractions import Fraction

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(n**0.5)
    return sqrt_n**2 == n

def check_rational_points(limit):
    solutions = []
    for q in range(1, limit):
        for p in range(1, limit):
            X = Fraction(p, q)
            # Y^2 = -X^4 + 10X^2 - 1
            # Y^2 = -(p/q)^4 + 10(p/q)^2 - 1
            # Y^2 = (-p^4 + 10p^2q^2 - q^4) / q^4
            numerator = -p**4 + 10*p**2*q**2 - q**4
            if numerator >= 0 and is_square(numerator):
                solutions.append((Fraction(p, q), numerator))
    return solutions

