def find_square_r2(limit):
    square_r2_solutions = []
    for y in range(1, limit):
        for x in range(-limit, limit):
            z_sq = x**2 - 3*x*y + 2*y**2
            if z_sq >= 0:
                z = int(z_sq**0.5)
                if z*z == z_sq:
                    r_sq = Fraction(x, y)
                    if r_sq >= 0:
                        # Check if r_sq is a square of a rational
                        # r_sq = (p/q)^2 => x/y = p^2/q^2
                        # This means x*q^2 = y*p^2
                        # Let's just check if Fraction(r_sq).numerator and denominator are squares
                        num = r_sq.numerator
                        den = r_sq.denominator
                        if num == 0:
                            square_r2_solutions.append((r_sq, "0"))
                        elif int(num**0.5)**2 == num and int(den**0.5)**2 == den:
                            square_r2_solutions.append((r_sq, "Square"))
    return square_r2_solutions

print(find_square_r2(100))

def find_solutions_fixed_large(limit):
    solutions = []
    for x in range(-limit, limit):
        if x == 0:
            solutions.append((Fraction(0), Fraction(0)))
            continue
        for y in range(1, limit):
            if x == 2*y:
                continue
            num = x * (x**2 - 2*x*y - y**2)
            den = y**2 * (x - 2*y)
            if den != 0:
                if num / den > 0:
                    prod = num * den
                    root = int(prod**0.5)
                    if root**2 == prod:
                        b = Fraction(root, abs(den))
                        if b**2 == Fraction(num, den):
                            solutions.append((Fraction(x, y), b))
    return solutions

print(find_solutions_fixed_large(200))

