def solve_large():
    solutions = []
    for y in range(1, 201):
        for x in range(-200, 201):
            if x == 2 * y:
                continue
            a = Fraction(x, y)
            # b^2 = a^2 - a/(a-2)
            num = a**3 - 2*a**2 - a
            den = a - 2
            b_sq = num / den
            if b_sq >= 0:
                num_b = b_sq.numerator
                den_b = b_sq.denominator
                prod = num_b * den_b
                root = int(prod**0.5)
                if root * root == prod:
                    solutions.append((a, Fraction(root, den_b)))
    return sorted(list(set(solutions)))

print(solve_large())
